import { useEffect, useState } from "react";
import { motion } from "framer-motion";

export default function Testimonials() {
  const [reviews, setReviews] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetch("http://localhost:5001/admin/reviews")
      .then((res) => res.json())
      .then((data) => {
        const activeReviews = data.filter(
          (r) => r.status === "Active"
        );
        setReviews(activeReviews);
      })
      .catch((err) => console.error("Reviews fetch error:", err))
      .finally(() => setLoading(false));
  }, []);

  return (
    <section
      id="testimonials"
      className="bg-black pt-32 pb-28 px-6 relative overflow-hidden"
    >
      {/* SUBTLE GOLD GLOW */}
      <div className="absolute top-0 left-1/2 -translate-x-1/2 w-[700px] h-[700px]
                      bg-[#e9b21a]/10 blur-[180px] pointer-events-none" />

      <div className="max-w-6xl mx-auto relative z-10">
        {/* HEADING */}
        <motion.h2
          initial={{ opacity: 0, y: 40 }}
          whileInView={{ opacity: 1, y: 0 }}
          viewport={{ once: true }}
          transition={{ duration: 0.7 }}
          className="text-center text-4xl md:text-5xl font-bold text-white mb-4"
        >
          Voices of <span className="text-[#e9b21a]">BodyZeal</span>
        </motion.h2>

        <p className="text-center text-gray-400 max-w-2xl mx-auto mb-20">
          Discipline. Consistency. Transformation.  
          Hear directly from members who live the BodyZeal mindset.
        </p>

        {/* LOADING */}
        {loading && (
          <p className="text-center text-gray-400">
            Loading testimonials...
          </p>
        )}

        {/* EMPTY */}
        {!loading && reviews.length === 0 && (
          <p className="text-center text-gray-400">
            No testimonials available yet.
          </p>
        )}

        {/* TESTIMONIAL STREAM */}
        <div className="space-y-20">
          {reviews.map((r, i) => (
            <motion.div
              key={r.id}
              initial={{ opacity: 0, y: 50 }}
              whileInView={{ opacity: 1, y: 0 }}
              viewport={{ once: true }}
              transition={{ duration: 0.6, delay: i * 0.1 }}
              className="relative pl-10 md:pl-20"
            >
              {/* VERTICAL LINE */}
              <div className="absolute left-2 md:left-8 top-0 h-full w-px bg-gradient-to-b
                              from-transparent via-[#e9b21a]/40 to-transparent" />

              {/* QUOTE MARK */}
              <div className="absolute -left-1 md:left-4 -top-4 text-7xl
                              text-[#e9b21a]/40 font-serif">
                “
              </div>

              {/* MESSAGE */}
              <p className="text-xl md:text-2xl text-gray-200 leading-relaxed font-light max-w-3xl">
                {r.message}
              </p>

              {/* META */}
              <div className="mt-6 flex flex-wrap items-center gap-6">
                {/* NAME */}
                <span className="text-[#e9b21a] font-semibold text-lg tracking-wide">
                  {r.name}
                </span>

                {/* STARS */}
                <div className="flex gap-1 text-lg">
                  {Array.from({ length: 5 }).map((_, idx) => (
                    <span
                      key={idx}
                      className={
                        idx < r.rating
                          ? "text-[#e9b21a]"
                          : "text-gray-600"
                      }
                    >
                      ★
                    </span>
                  ))}
                </div>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
